import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 처리 구분은 승인·반려만 받는다 (API 오류 조건 기준, 보류는 거절)
const ALLOWED_ACTIONS = ['승인', '반려'];

@Controller('api/v1')
export class FnSfr04007Controller {
  @Post('/approval-lines/:approvalLineId/process')
  @HttpCode(200)
  async processApprovalLine(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const lineId = req.params['approvalLineId'];
    if (!/^[0-9]+$/.test(lineId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재선 ID가 올바르지 않습니다.');
    }
    const actionType = typeof data['actionType'] === 'string' ? data['actionType'] : '';
    if (actionType === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '처리 유형을 선택해 주세요.');
    }
    if (!ALLOWED_ACTIONS.includes(actionType)) {
      throw new ApiError(422, 'APPROVAL_ACTION_INVALID', '처리 유형은 승인 또는 반려만 가능합니다.');
    }
    const rawOpinion = data['opinion'];
    if (rawOpinion !== undefined && rawOpinion !== null && typeof rawOpinion !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재 의견 형식이 올바르지 않습니다.');
    }
    const opinion = typeof rawOpinion === 'string' && rawOpinion.trim() !== '' ? rawOpinion.trim() : null;
    if (actionType === '반려' && opinion === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '반려할 때는 결재 의견을 입력해 주세요.');
    }

    return transaction(async (db) => {
      const lines = await db.query(
        'SELECT l.approval_line_id AS "approvalLineId", l.approval_document_id AS "documentId", l.approver_id AS "approverId", l.line_group AS "lineGroup", l.sequence_no AS "sequenceNo", l.action_type AS "actionType", d.approval_status AS "documentStatus" ' +
          'FROM approval_line l JOIN approval_document d ON d.approval_document_id = l.approval_document_id ' +
          'WHERE l.approval_line_id = CAST(:lineId AS bigint)',
        { lineId },
      );
      if (lines.length === 0) {
        throw new ApiError(404, 'APPROVAL_LINE_NOT_FOUND', '결재선을 찾을 수 없습니다.');
      }
      const line = lines[0];
      const mine = await db.query(
        'SELECT CAST(:userId AS bigint) AS "userId"',
        { userId: user.id },
      );
      const isMine = String(line['approverId']) === String(mine[0]['userId']);
      const open = line['actionType'] === null && ['결재대기', '진행중'].includes(String(line['documentStatus']));
      if (!isMine || !open) {
        throw new ApiError(409, 'APPROVAL_NOT_MY_TURN', '결재 차례가 아니거나 이미 처리된 문서입니다.');
      }
      const before = await db.query(
        'SELECT COUNT(*) AS "cnt" FROM approval_line ' +
          'WHERE approval_document_id = CAST(:documentId AS bigint) AND line_group = CAST(:lineGroup AS integer) ' +
          'AND sequence_no < CAST(:sequenceNo AS integer) AND (action_type IS NULL OR action_type <> :approved)',
        { documentId: line['documentId'], lineGroup: line['lineGroup'], sequenceNo: line['sequenceNo'], approved: '승인' },
      );
      if (Number(before[0]['cnt']) > 0) {
        throw new ApiError(409, 'APPROVAL_NOT_MY_TURN', '결재 차례가 아니거나 이미 처리된 문서입니다.');
      }
      const done = await db.query(
        'UPDATE approval_line SET action_type = :actionType, opinion = :opinion, processed_at = now(), ' +
          'approver_id = CAST(:userId AS bigint), updated_at = now() ' +
          'WHERE approval_line_id = CAST(:lineId AS bigint) AND action_type IS NULL ' +
          'RETURNING approval_line_id AS "approvalLineId", action_type AS "actionType", processed_at AS "processedAt"',
        { actionType, opinion, userId: user.id, lineId },
      );
      if (done.length === 0) {
        throw new ApiError(409, 'APPROVAL_NOT_MY_TURN', '결재 차례가 아니거나 이미 처리된 문서입니다.');
      }
      let nextStatus = '반려';
      if (actionType === '승인') {
        const rest = await db.query(
          'SELECT COUNT(*) AS "cnt" FROM approval_line ' +
            'WHERE approval_document_id = CAST(:documentId AS bigint) AND action_type IS NULL',
          { documentId: line['documentId'] },
        );
        nextStatus = Number(rest[0]['cnt']) > 0 ? '진행중' : '승인';
      }
      await db.execute(
        'UPDATE approval_document SET approval_status = :status, updated_at = now() ' +
          'WHERE approval_document_id = CAST(:documentId AS bigint)',
        { status: nextStatus, documentId: line['documentId'] },
      );
      return done[0];
    });
  }
}

