import { useState } from 'react';
import {
  call,
  Badge,
  DataTable,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  RefName,
  Select,
  TextInput,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr04007Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [lineId, setLineId] = useState<number | string>('');
  const [actionType, setActionType] = useState('');
  const [opinion, setOpinion] = useState('');

  const approved = results.filter((r) => r['actionType'] === '승인').length;
  const rejected = results.filter((r) => r['actionType'] === '반려').length;

  function openDrawer() {
    setLineId('');
    setActionType('');
    setOpinion('');
    setOpen(true);
  }

  async function submit() {
    if (lineId === '') {
      throw new Error('결재선을 선택해 주세요.');
    }
    if (actionType === '') {
      throw new Error('처리 유형을 선택해 주세요.');
    }
    if (actionType === '반려' && opinion.trim() === '') {
      throw new Error('반려할 때는 결재 의견을 입력해 주세요.');
    }
    const result = await call('POST', '/approval-lines/' + lineId + '/process', role, {
      actionType,
      opinion: opinion.trim(),
    });
    setResults([result, ...results]);
    setOpen(false);
    notify(actionType === '승인' ? '승인했습니다.' : '반려했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>처리 건수</h2>
        <Tiles items={[['이번 처리', results.length]]} />
      </section>
      <section className="box span-4">
        <h2>승인</h2>
        <Tiles items={[['승인 건수', approved]]} />
      </section>
      <section className="box span-4">
        <h2>반려</h2>
        <Tiles items={[['반려 건수', rejected]]} />
      </section>
      <section className="box span-12">
        <h2>결재 처리 결과</h2>
        <button type="button" onClick={openDrawer}>
          결재 처리
        </button>
        <DataTable
          columns={[
            {
              key: 'approvalLineId',
              label: '결재선 ID',
              render: (row) => <RefName table="approval_line" role={role} value={row['approvalLineId']} />,
            },
            { key: 'actionType', label: '처리 유형', render: (row) => <Badge value={row['actionType']} /> },
            { key: 'processedAt', label: '처리 일시', render: (row) => <DateText value={row['processedAt']} time /> },
          ]}
          rows={results}
          empty="처리한 결재문서가 없습니다."
        />
      </section>
      {open && (
        <Drawer title="결재문서 승인·반려" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="처리">
            <Field label="결재선 ID" required>
              <LookupSelect table="approval_line" role={role} value={lineId} onChange={setLineId} />
            </Field>
            <Field label="처리 유형" required>
              <Select
                value={actionType}
                onChange={setActionType}
                options={[
                  ['승인', '승인'],
                  ['반려', '반려'],
                ]}
              />
            </Field>
            <Field label="결재 의견" wide hint="반려할 때는 필수입니다.">
              <TextInput value={opinion} onChange={setOpinion} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
